SINA_SMART["hemato1-primary"] = {"lecture":"hemato1-primary","title":"Primary haemostasis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-primary:e0","text":"Two functions: rapid local plug; fluid blood elsewhere.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e1","text":"Primary haemostasis: temporary platelet plug; coagulation reinforces it.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e2","text":"GPIb binds VWF (adhesion); GPIIb/IIIa binds fibrinogen (aggregation).","topic":"Actors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e3","text":"α-granules: VWF, fibrinogen, factor V, PF4; dense: ADP, ATP, Ca²⁺, serotonin.","topic":"Actors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e4","text":"Thrombocytopenia < 150,000; thrombocytosis > 400,000/mm³.","topic":"Actors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e5","text":"Intact endothelium prevents clotting; subendothelium is thrombogenic.","topic":"Actors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e6","text":"VWF: carries factor VIII, bridges collagen to GPIb.","topic":"Actors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e7","text":"Adhesion → activation (shape change, secretion, TXA2, PS flip, recruitment) → aggregation.","topic":"Steps","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e8","text":"TXA2: COX-1 pathway; aspirin blocks COX-1 irreversibly (~10 days).","topic":"Steps","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-primary:e9","text":"Glanzmann: GPIIb/IIIa; Bernard-Soulier: GPIb.","topic":"Steps","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1prd5jr":"a","1mk2fy7":"a","7tlfpr":"a","1ne1yj9":"a","1uf1p7g":"a","72gsds":"a","cxq9mw":"a","10s925o":"a","1u7qe6n":"a","wye70s":"a","834rf8":"a","1suowky":"a","1mew5ca":"a","1upu30w":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-primary:e0":{"s":0,"u":["Two functions: rapid local plug; fluid blood elsewhere.","Haemostasis ('blood standing still') has two functions: a rapid, localised plug at a vascular injury, and keeping blood fluid elsewhere and after healing."],"dp":[]},"hemato1-primary:e1":{"s":0,"u":["Primary haemostasis: temporary platelet plug; coagulation reinforces it.","Primary haemostasis builds a temporary platelet plug , 'like a bottle stopper', which coagulation (secondary haemostasis) then reinforces: platelets are the bricks, fibrin the mortar."],"dp":[{"h":"Why primary haemostasis defects cause skin and mucosal bleeding","t":"Platelets and von Willebrand factor act first at small vessels, the capillaries of skin and mucosa. When they fail, bleeding appears as petechiae, easy bruising, nosebleeds, gum bleeding and heavy periods, and starts immediately after a cut. Coagulation factor defects such as haemophilia instead cause deep bleeding into joints and muscles, often delayed. This pattern helps guide the first tests. Source: the lecture's primary haemostasis steps and actors."}]},"hemato1-primary:e2":{"s":1,"u":["GPIb binds VWF (adhesion); GPIIb/IIIa binds fibrinogen (aggregation).","Platelets : membrane phospholipids (arachidonic acid → thromboxane A2 , PAF, platelet factor 3), surface glycoproteins GPIb (binds VWF) and GPIIb/IIIa (binds fibrinogen), antigens (ABO, HLA, HPA); an open canalicular system (secretion channel); a cytoskeleton (actin, myosin, tubulin: shape change and clot retraction); α-granules (8-10 per platelet: PF4, VWF, factor V, β-thromboglobulin, fibrinogen), dense granules (4-5: ADP, ATP, Ca²⁺, serotonin), lysosomes, glycogen, and the dense tubular system (cyclooxygenase, calcium).","Plasma proteins : VWF (large multimer from endothelium and megakaryocytes; carries and protects factor VIII ; bridges collagen to GPIb) and fibrinogen (liver; ligand of GPIIb/IIIa in aggregation; cleaved by thrombin into fibrin in coagulation)."],"dp":[]},"hemato1-primary:e3":{"s":1,"u":["α-granules: VWF, fibrinogen, factor V, PF4; dense: ADP, ATP, Ca²⁺, serotonin.","Platelets : membrane phospholipids (arachidonic acid → thromboxane A2 , PAF, platelet factor 3), surface glycoproteins GPIb (binds VWF) and GPIIb/IIIa (binds fibrinogen), antigens (ABO, HLA, HPA); an open canalicular system (secretion channel); a cytoskeleton (actin, myosin, tubulin: shape change and clot retraction); α-granules (8-10 per platelet: PF4, VWF, factor V, β-thromboglobulin, fibrinogen), dense granules (4-5: ADP, ATP, Ca²⁺, serotonin), lysosomes, glycogen, and the dense tubular system (cyclooxygenase, calcium)."],"dp":[]},"hemato1-primary:e4":{"s":1,"u":["Thrombocytopenia < 150,000; thrombocytosis > 400,000/mm³.","Quantitative abnormalities: thrombocytopenia &lt; 150,000/mm³ (marrow failure: aplasia, leukaemia, toxins, drugs, viruses such as EBV and COVID-19; peripheral destruction: immune thrombocytopenia, quinine, pregnancy) and thrombocytosis &gt; 400,000/mm³ (inflammation, splenectomy, essential thrombocythaemia); qualitative defects such as glycoprotein deficiencies."],"dp":[]},"hemato1-primary:e5":{"s":1,"u":["Intact endothelium prevents clotting; subendothelium is thrombogenic.","Vessel wall : intact endothelium actively prevents clotting (prostacyclin, heparan sulfate, inhibitors, fibrinolysis activators); injured, it secretes VWF, tissue factor and fibrinolysis inhibitors; the subendothelium (collagen, VWF, tissue factor) is thrombogenic."],"dp":[]},"hemato1-primary:e6":{"s":1,"u":["VWF: carries factor VIII, bridges collagen to GPIb.","Plasma proteins : VWF (large multimer from endothelium and megakaryocytes; carries and protects factor VIII ; bridges collagen to GPIb) and fibrinogen (liver; ligand of GPIIb/IIIa in aggregation; cleaved by thrombin into fibrin in coagulation).","Vessel wall : intact endothelium actively prevents clotting (prostacyclin, heparan sulfate, inhibitors, fibrinolysis activators); injured, it secretes VWF, tissue factor and fibrinolysis inhibitors; the subendothelium (collagen, VWF, tissue factor) is thrombogenic."],"dp":[]},"hemato1-primary:e7":{"s":2,"u":["Adhesion → activation (shape change, secretion, TXA2, PS flip, recruitment) → aggregation.","Activation : shape change; secretion of dense granules (serotonin: vasoconstriction; ADP : aggregating agent; Ca²⁺) and α-granules (VWF, fibrinogen, PF4, which neutralises heparin and attracts white cells); the prostaglandin pathway : phospholipase A2 releases arachidonic acid → COX-1 → PGG2/PGH2 → thromboxane synthase → TXA2 (vasoconstriction, activates neighbours); phosphatidylserine flips to the outer leaflet, providing a surface for coagulation complexes; ADP, TXA2 and thrombin recruit more platelets (amplification).","Aggregation : activation switches GPIIb/IIIa to high affinity; fibrinogen bridges adjacent platelets, forming the primary plug."],"dp":[]},"hemato1-primary:e8":{"s":2,"u":["TXA2: COX-1 pathway; aspirin blocks COX-1 irreversibly (~10 days).","Aspirin irreversibly acetylates COX-1; platelets cannot regenerate it, so the effect lasts about 10 days ; low dose (75-325 mg/day) prevents thrombosis.","Activation : shape change; secretion of dense granules (serotonin: vasoconstriction; ADP : aggregating agent; Ca²⁺) and α-granules (VWF, fibrinogen, PF4, which neutralises heparin and attracts white cells); the prostaglandin pathway : phospholipase A2 releases arachidonic acid → COX-1 → PGG2/PGH2 → thromboxane synthase → TXA2 (vasoconstriction, activates neighbours); phosphatidylserine flips to the outer leaflet, providing a surface for coagulation complexes; ADP, TXA2 and thrombin recruit more platelets (amplification)."],"dp":[]},"hemato1-primary:e9":{"s":2,"u":["Glanzmann: GPIIb/IIIa; Bernard-Soulier: GPIb.","Exploration includes the platelet count and smear, platelet function analyser or bleeding time, VWF activity, aggregometry and flow cytometry (GPIIb/IIIa deficiency = Glanzmann thrombasthenia ; GPIb deficiency = Bernard-Soulier syndrome )."],"dp":[]}},"meta":{"1prd5jr":{"a":"recall","vg":"hemato1-primary:e0/recall/1"},"1mk2fy7":{"a":"recall","vg":"hemato1-primary:e1/recall/1"},"7tlfpr":{"a":"recall","vg":"hemato1-primary:e2/recall/1"},"1ne1yj9":{"a":"recall","vg":"hemato1-primary:e2/recall/2"},"1uf1p7g":{"a":"recall","vg":"hemato1-primary:e3/recall/1"},"72gsds":{"a":"recall","vg":"hemato1-primary:e6/recall/1"},"cxq9mw":{"a":"recall","vg":"hemato1-primary:e5/recall/1"},"10s925o":{"a":"recall","vg":"hemato1-primary:e7/recall/1"},"1u7qe6n":{"a":"recall","vg":"hemato1-primary:e3/recall/2"},"wye70s":{"a":"recall","vg":"hemato1-primary:e8/recall/1"},"834rf8":{"a":"recall","vg":"hemato1-primary:e7/recall/2"},"1suowky":{"a":"recall","vg":"hemato1-primary:e9/recall/1"},"1mew5ca":{"a":"recall","vg":"hemato1-primary:e9/recall/2"},"1upu30w":{"a":"recall","vg":"hemato1-primary:e7/recall/3"}},"explRev":"34513f45386b"};
